To make predictions only keep detections above a certain certainty, you can use the `confidence_threshold` parameter when running inference with the YOLO26 model. Here's how you can do it:

```python
@app.post(AIP_PREDICT_ROUTE, response_model=PredictionResponse)
async def predict(request: PredictionRequest):
    """Prediction endpoint for Vertex AI."""
    try:
        predictions = []

        for instance in request.instances:
            if isinstance(instance, dict):
                if "image" in instance:
                    image_data = base64.b64decode(instance["image"])
                    input_image = get_image_from_bytes(image_data)
                else:
                    raise HTTPException(status_code=400, detail="Instance must contain 'image' field")
            else:
                raise HTTPException(status_code=400, detail="Invalid instance format")

            # Extract YOLO26 parameters if provided
            parameters = request.parameters or {}
            confidence_threshold = parameters.get("confidence", 0.5)
            return_annotated_image = parameters.get("return_annotated_image", False)

            # Run inference with YOLO26n model
            result = run_inference(input_image, confidence_threshold=confidence_threshold)
            detections_list = result["detections"]

            # Format predictions for Vertex AI
            detections = []
            for detection in detections_list:
                formatted_detection = {
                    "class": detection["class"],
                    "confidence": detection["confidence"],
                    "bbox": detection["bbox"]
                }
                if formatted_detection["confidence"] >= confidence_threshold:
                    detections.append(formatted_detection)

            # Add detections to the predictions list
            predictions.append({"detections": detections})

        return {"predictions": predictions}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
```

In this example, the `confidence_threshold` is set to 0.5 by default. You can adjust this value based on your requirements. Only detections with a confidence score greater than or equal to the threshold are included in the final predictions.
